INSERT INTO sedes(nombre,direccion) VALUES ('Casuarinas','Av. Central, Nuevo Chimbote'),('San Luis','Urb. San Luis, Nuevo Chimbote') ON CONFLICT DO NOTHING;
INSERT INTO almacenes(sede_id,nombre) SELECT sede_id,'Almacén principal' FROM sedes WHERE nombre IN('Casuarinas','San Luis') ON CONFLICT DO NOTHING;
